unitsize(5mm);
defaultpen(linewidth(.7pt)+fontsize(8pt));

real r=2*sqrt(3), h=r/2;

pair A=r*dir(0), B=r*dir(60), C=r*dir(180), F=foot(B,A,C);

draw(circumcircle(B,F,Cr),linetype("2 2']);

draw(B--F--C--cycle);

draw(A--B--C--cycle);

draw(rightanglemark(A,B,C,8));
draw(rightanglemark(B,F,C,8));

draw(B--(0,h));

label("$3$",(A+F)/2,NW);

